import fetch from 'node-fetch';

const API_URL = 'http://localhost:3001/api';

async function test() {
  console.log('1. Fetching all events...');
  let res = await fetch(`${API_URL}/public/events`);
  console.log(await res.json());

  console.log('\n2. Creating an event...');
  res = await fetch(`${API_URL}/staff/events`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer test-token' }, // Wait, auth requires real token
    body: JSON.stringify({
      title: 'Test Event',
      description: 'Testing upload',
      imageBase64: 'data:image/jpeg;base64,'
    })
  });
  console.log('Status:', res.status);
  
}

test();
